#script to extract variables of interest from CSV-format UK Biobank data
# script authors: Cathy Wyse & Amber Roguski

######### CSV extract
## Primary demographics ####################

#change this to the directory where the data are stored
setwd("C:/Users/cwyse/Downloads/UKB summer download")

#import data
Primary_Demographics <- read.csv("./ukb673864_Primary_Demographics.csv")

#make new data frame to store variables
UKB_master <- data.frame(Primary_Demographics$eid) 
comment(UKB_master )<-c("Data for timing proposal")
colnames(UKB_master)[1]<-"eid"

#sex  
Primary_Demographics$X31.0.0 <- factor(Primary_Demographics$X31.0.0, levels=lvl.0009, labels=lbl.0009)
sex <- Primary_Demographics$X31.0.0
comment(sex)<-c("Datafield=31.0.0")

#year of birth
year_born <- Primary_Demographics$X34.0.0
comment(year_born   )<-c("Datafield = 34.0.0")

#month of birth
Primary_Demographics$X52.0.0 <- factor(Primary_Demographics$X52.0.0, levels=lvl.0008, labels=lbl.0008)
month_born <- Primary_Demographics$X52.0.0
comment(month_born)<-c("Datafield = 52.0.0")

#assess_date
Primary_Demographics$X53.0.0 <- as.Date(Primary_Demographics$X53.0.0)
assess_date <- Primary_Demographics$X53.0.0
comment(assess_date)<-c("Datafield = 53.0.0")

#ethnicity
ethnic <- Primary_Demographics$X21000.0.0
Primary_Demographics$X21000.0.0 <- factor(Primary_Demographics$X21000.0.0, levels=lvl.1001, labels=lbl.1001)
comment(ethnic)<-c("Datafield = 21000.0.0")

#age
age <- Primary_Demographics$X21003.0.0
comment(age   )<-c("Datafield = 21003.0.0  ")

#add variables to master dataframe
UKB_master <- cbind(UKB_master,sex,month_born,year_born,assess_date,ethnic,age)

rm(Primary_Demographics)

## Mental health ######################################

#import data
mental_health <- read.csv("./ukb673864_mental_health.csv")

#seen GP nerves, anxiety, depression X2090.0.0
mental_health$X2090.0.0 <- factor(mental_health$X2090.0.0, levels=lvl.100349, labels=lbl.100349)
depress_gp <- mental_health$X2090.0.0
comment(depress_gp)<-c("Datafield = 2090.0.0  ")

#seen psychiatrist nerves, anxiety, depression X2100.0.0
mental_health$X2100.0.0 <- factor(mental_health$X2100.0.0, levels=lvl.100349, labels=lbl.100349)
depress_psych <- mental_health$X2100.0.0
comment(depress_psych)<-c("Datafield = 2100.0.0")

UKB_master <- cbind(UKB_master,depress_gp, depress_psych)

rm(mental_health)
## Physical Measures #############

#import data
physical_measures <- read.csv("./ukb673864_physical_measures.csv")

#acceleration average
accel_mean <- physical_measures$X90012.0.0
comment( accel_mean  )<-c("Datafield = X90012.0.0  ")

#systolic automated reading 4080
systolic <- physical_measures$X4079.0.0
comment(systolic   )<-c("Datafield = 4080.0.0  ")

#diastolic automated reading 4079
diastolic <- physical_measures$X4079.0.0
comment(diastolic   )<-c("Datafield = 4079.0.0  ")

#pulse
pulse <- physical_measures$X102.0.0
comment(pulse   )<-c("Datafield = X102.0.0  ")

#body fat percentage from IP - 23099
body_fat <- physical_measures$X23099.0.0
comment (body_fat)<-c("Datafield = 23099.0.0  ")

#BMI 21001
BMI <- physical_measures$X21001.0.0
comment (BMI)<-c("Datafield = 21001.0.0  ")

#hand grip 46 left
handgripL <- physical_measures$X46.0.0
comment (handgripL)<-c("Datafield = 46")

#hand grip 47 right
handgripR <- physical_measures$X47.0.0
comment (handgripR)<-c("Datafield = 47  ")

#FEV 3063
FEV <- physical_measures$X3063.0.0
comment (FEV)<-c("Datafield = 3063  ")

#FEV 3062
FVC <- physical_measures$X3062.0.0
comment (FVC)<-c("Datafield = 3062  ")

#FEV 3064
PEF <- physical_measures$X3064.0.0
comment (PEF)<-c("Datafield = 3064  ")

UKB_master <- cbind(UKB_master,accel_mean,systolic,diastolic, pulse, body_fat, BMI, handgripL, handgripR, FEV, FVC, PEF)

rm(physical_measures)
## Geographic Location  #############################################

#import data
geographic <- read.csv("./ukb673864_geographic.csv")

#	Home area population density - urban or rural -20118
urban <- geographic$X20118.0.0
comment (urban)<-c("Datafield = 20118.0.0  ")

#assessment centre
centre <- as.integer(geographic$X54.0.0)
comment(centre)<-c("Datafield = 54.0.0")

#make latitude table for merge
eid <- as.data.frame(geographic$eid)
names(eid)<- "eid"
centre <- as.data.frame(centre)
eid_centre <- cbind(eid,centre)

#merge eid_centre and latitude
latitude_with_eid <- merge(eid_centre,Table_latitude_assesment_centres, by="centre")
latitude_with_eid <- latitude_with_eid[order(latitude_with_eid$eid),] 

UKB_master <- cbind(UKB_master,centre,urban)

#merge final data frame to extract latitude and longitude and centre id
UKB_master <- merge(UKB_master, latitude_with_eid[,c("eid","lat","long","short_name")], by="eid")

rm(geographic)
rm(centre)
rm(eid)
rm(latitude_with_eid)
rm(Table_latitude_assesment_centres)
rm(eid_centre)

## Self Report Medical  #############################################


Self.report.medical <- read.csv("./ukb673864_Self-report medical.csv")

#Data-Field 2178	Overall health rating
Self.report.medical$X2178.0.0 <- factor(Self.report.medical$X2178.0.0, levels=lvl.100508, labels=lbl.100508)
health_self_report <- Self.report.medical$X2178.0.0
comment (health_self_report)<-c("Datafield = 2178  ")

UKB_master <- cbind(UKB_master,health_self_report)

rm(Self.report.medical)

## Education  #############################################

education <- read.csv("./ukb673864_education_job.csv")

#	Qualifications 6138
education$X6138.0.0 <- factor(education$X6138.0.0, levels=lvl.100305, labels=lbl.100305)
qualifications <- education$X6138.0.0
comment (qualifications)<-c("Datafield = 6138  ")

#	Current employment status 6142
education$X6142.0.0 <- factor(education$X6142.0.0, levels=lvl.100295, labels=lbl.100295)
employed <- education$X6142.0.0
comment (employed)<-c("Datafield = 6142  ")

#	Job involves night shift work 3426
education$X3426.0.0 <- factor(education$X3426.0.0, levels=lvl.100301, labels=lbl.100301)
night_shift <- education$X3426.0.0
comment (night_shift)<-c("Datafield = 3426  ")

#	Job involves shift work 826
education$X826.0.0 <- factor(education$X826.0.0, levels=lvl.100301, labels=lbl.100301)
shift_work <- education$X826.0.0
comment (shift_work)<-c("Datafield = 826  ")

UKB_master <- cbind(UKB_master,qualifications,employed, night_shift, shift_work)

rm(education)

## Sleep and Alcohol  #############################################

sleep_alcohol <- read.csv("./ukb673864_sleep_alcohol.csv")

#1160	Sleep duration
sleep_duration<- sleep_alcohol$X1160.0.0
comment (sleep_duration)<-c("Datafield = 1160  ")

#1170	Getting up in morning	
sleep_alcohol$X1170.0.0 <- factor(sleep_alcohol$X1170.0.0, levels=lvl.100341, labels=lbl.100341)
getting_up  <- sleep_alcohol$X1170.0.0
comment (getting_up)<-c("Datafield = 1170  ")

#1180	Morning/evening person (chronotype)	
sleep_alcohol$X1180.0.0 <- factor(sleep_alcohol$X1180.0.0, levels=lvl.100342, labels=lbl.100342)
chronotype <- sleep_alcohol$X1180.0.0
comment (chronotype)<-c("Datafield = 1180")

#1190	Nap during day
sleep_alcohol$X1190.0.0 <- factor(sleep_alcohol$X1190.0.0, levels=lvl.100343, labels=lbl.100343)
day_naps <- sleep_alcohol$X1190.0.0
comment (day_naps)<-c("Datafield = 1190")

#1200	Sleeplessness / insomnia
sleep_alcohol$X1200.0.0 <- factor(sleep_alcohol$X1200.0.0, levels=lvl.100343, labels=lbl.100343)
insomnia <- sleep_alcohol$X1200.0.0
comment (insomnia)<-c("Datafield = 1200")

#1210 	Snoring
sleep_alcohol$X1210.0.0 <- factor(sleep_alcohol$X1210.0.0, levels=lvl.100345, labels=lbl.100345)
snoring <- sleep_alcohol$X1210.0.0
comment (snoring)<-c("Datafield = 1210")

#1220	Daytime dozing / sleeping	
sleep_alcohol$X1220.0.0 <- factor(sleep_alcohol$X1220.0.0, levels=lvl.100346, labels=lbl.100346)
day_sleepiness <- sleep_alcohol$X1220.0.0
comment (day_sleepiness)<-c("Datafield = 1220")

#this variable was retrieved separately
alcohol <- read.delim("./ukb673864_alcohol.tab")

#1558	Alcohol
alcohol$X1558.0.0 <- factor(alcohol$X1558.0.0, levels=lvl.100402, labels=lbl.100402)
alcohol <- alcohol$X1558.0.0
comment (alcohol)<-c("Datafield = 1558")

UKB_master <- cbind(UKB_master,alcohol, snoring, day_sleepiness, day_naps, chronotype, sleep_duration, insomnia, getting_up)

rm(sleep_alcohol)
rm(alcohol)





